import {createWarehouseGame,migrateWarehouseGame,advanceWarehouse,warehouseStats,warehouseCosts,warehouseNow,warehouseFixture,WAREHOUSE_ROLES,FULFILLMENT_PLANS,DELIVERY_AREAS,WH_ROBOT,quoteWarehouseSupply,buyWarehouseSupply,setWarehouseStaff,setWarehouseRobots,upgradeWarehouse,setWarehousePolicy,acceptWarehouseContract,dispatchWarehouse,moveWarehouseFixture,stockValuation} from './engine.js';
import {createWarehouseScene} from './scene.js';
import {makeSave} from './save-format.js';
import {createSaveManager} from './save-manager.js';
import {startOfflineSupport} from './offline.js';
const $=id=>document.getElementById(id),state=createWarehouseGame();
const euro=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n),num=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0}).format(n),clock=n=>`${String(Math.floor(n%1440/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
const phaseNames={queued:'À préparer',picking:'Prélèvement',await_pack:'À emballer',packing:'Emballage',ready:'Prêt au départ',in_transit:'En livraison',delivered:'Livré'},workerPhases={idle:'Disponible',to_rack:'Vers le stock',collecting:'Prélèvement',to_pack:'Vers l’emballage',to_truck:'Vers le quai',loading:'Chargement',to_stock:'Mise en stock',to_bench:'Vers le poste',packing:'Emballage',driving:'En tournée',to_home:'Retour au poste'};
const titles={orders:'Commandes',stock:'Stock & achats',inbound:'Réception',production:'Préparation & emballage',dispatch:'Tournées de livraison',team:'Équipes',robots:'Robots autonomes',finance:'Finances & journées'};
let saveManager,saveUi,offlineSupport,offlineMessage='',panel=null,selectedProduct=null,filter='active',arranging=false,held=false,lastPanel='',lastPanelAt=0,lastTime=performance.now(),pendingMinutes=0,noticeTimer,lastLogKey='';
const quantities=Object.fromEntries(state.products.map(p=>[p.id,240]));
const scene=createWarehouseScene($('warehouse-map'),state,data=>{if(data.arranging){$('layout-message').textContent=(data.productId?state.products.find(p=>p.id===data.productId).name:'Poste d’emballage')+' sélectionné · touchez sa nouvelle place.';return;}selectedProduct=data.productId||null;openPanel(data.tab);},(key,x,z)=>act(()=>moveWarehouseFixture(state,key,x,z,warehouseFixture(state,key).rotation),'Agencement enregistré.'));
function notice(message){$('notice').textContent=message;$('notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').hidden=true,4500);}
function act(action,message){if(!saveManager?.ready){notice('Chargez votre partie avant de modifier les opérations.');return false;}try{const result=action();saveManager.changed();lastPanel='';lastPanelAt=-1e9;render();if(message)notice(message);return result??true;}catch(error){notice(error.message);return false;}}
function openPanel(tab){if(!titles[tab])return;panel=tab;$('management-panel').hidden=false;$('management-panel').classList.toggle('wide',tab==='finance');$('panel-heading').textContent=titles[tab];lastPanel='';lastPanelAt=-1e9;render();}
function closePanel(){panel=null;$('management-panel').hidden=true;document.querySelectorAll('.world-tools button').forEach(b=>b.classList.remove('active'));render();}
const orderItems=o=>o.lines.map(l=>`${l.quantity} × ${state.products.find(p=>p.id===l.productId).short}`).join(' · ');
function orderCard(o){const late=o.stage!=='delivered'&&warehouseNow(state)>o.deadline,remaining=o.deadline-warehouseNow(state);return `<article class="card" data-order-id="${o.id}"><div class="card-head"><strong>${o.ref}</strong><span class="chip ${o.channel==='express'?'express':''}">${o.channel==='express'?'Express':'Standard'}</span><span class="chip ${late?'late':o.stage==='delivered'?'good':''}">${late?'En retard':phaseNames[o.stage]}</span></div><p class="order-lines">${orderItems(o)}</p><div class="row"><span class="muted">${DELIVERY_AREAS.find(a=>a.id===o.area).name} · ${o.stage==='delivered'?'livré '+clock(o.deliveredAt):'avant '+clock(o.deadline)+(remaining<60&&remaining>=0?' · '+remaining+' min':'')}</span><strong>${euro(o.paid??o.value)}</strong></div></article>`;}
function contractsPanel(){return state.contracts.filter(c=>c.status==='accepted'||c.status==='offered'&&warehouseNow(state)>=c.opens&&warehouseNow(state)<=c.expires).map(c=>{const done=c.orders.filter(id=>state.orders.find(o=>o.id===id)?.stage==='delivered').length;return `<article class="card"><div class="card-head"><strong>${c.name}</strong><span class="chip express">+ ${euro(c.bonus)}</span></div><p>${c.description} · livraison avant ${clock(c.deadline)}</p>${c.status==='offered'?`<button data-contract="${c.id}" class="primary">Accepter le contrat</button>`:`<div class="progress"><span style="width:${done/c.count*100}%"></span></div><span class="muted">${done} / ${c.count} livrées · prime si tous les délais sont tenus</span>`}</article>`;}).join('');}
function ordersPanel(){const stats=warehouseStats(state),orders=[...state.orders].reverse().filter(o=>filter==='all'||filter==='active'&&o.stage!=='delivered'||filter==='express'&&o.channel==='express'&&o.stage!=='delivered'||filter==='late'&&o.stage!=='delivered'&&warehouseNow(state)>o.deadline);
 return `<div class="stat-grid"><div><span>À traiter</span><strong>${stats.active}</strong></div><div><span>En retard</span><strong>${stats.late}</strong></div></div><label>Commandes entrantes<select data-policy="plan">${Object.entries(FULFILLMENT_PLANS).map(([key,p])=>`<option value="${key}" ${state.plan===key?'selected':''}>${p.name}${key==='express'?' · délais courts, frais majorés':key==='volume'?' · plus de volume, frais réduits':''}</option>`).join('')}</select></label><label>Ordre de traitement<select data-policy="priority">${[['deadline','Échéances les plus proches'],['express','Express en premier'],['fifo','Premières entrées'],['sector','Regrouper les tournées par secteur']].map(([v,n])=>`<option value="${v}" ${state.priority===v?'selected':''}>${n}</option>`).join('')}</select></label><button data-intake="toggle" class="full">${state.acceptOrders?'Suspendre les nouvelles commandes':'Reprendre les commandes'}</button><h3 class="section-heading">Opportunités</h3>${contractsPanel()||'<p>Aucune offre disponible pour le moment.</p>'}<h3 class="section-heading">Suivi des commandes</h3><div class="filter-row">${[['active','En cours'],['express','Express'],['late','Retards'],['all','Toutes']].map(([v,n])=>`<button data-filter="${v}" class="${filter===v?'active':''}">${n}</button>`).join('')}</div>${orders.slice(0,45).map(orderCard).join('')||'<p class="list-empty">Aucune commande dans cette vue.</p>'}`;}
function stockPanel(){const ps=selectedProduct?[...state.products].sort((a,b)=>(b.id===selectedProduct)-(a.id===selectedProduct)):state.products;return ps.map(p=>{const q=quantities[p.id],normal=quoteWarehouseSupply(state,p.id,q,false),express=quoteWarehouseSupply(state,p.id,q,true);return `<article class="card" data-product-id="${p.id}"><div class="card-head"><strong><span style="color:${p.color}">●</span> ${p.name}</strong><span class="chip ${p.onHand-p.reserved<12?'late':''}">${p.onHand} / ${p.capacity}</span></div><div class="progress"><span style="width:${(p.onHand-p.reserved)/p.capacity*100}%;background:${p.color}"></span><span class="reserved" style="width:${p.reserved/p.capacity*100}%"></span><span class="incoming" style="width:${Math.max(0,Math.min(p.ordered,p.capacity-p.onHand))/p.capacity*100}%"></span></div><div class="row"><span class="muted">${p.onHand-p.reserved} disponibles · ${p.reserved} réservés</span><span class="muted">${p.ordered?'+ '+p.ordered+' attendus'+(p.onHand+p.ordered>p.capacity?' · '+(p.onHand+p.ordered-p.capacity)+' sans place':''):''}</span></div><div class="small-actions"><button data-upgrade="rack" data-product="${p.id}" ${p.capacity>=960?'disabled':''}>+ 240 places · 650 €</button></div><p class="muted">Achat ${euro(p.cost)} / article · carton de 24</p><div class="quantities">${[24,120,240,480].map(n=>`<button data-quantity="${n}" data-product="${p.id}" class="${q===n?'selected':''}">${n}</button>`).join('')}</div><div class="small-actions"><button data-buy="normal" data-product="${p.id}" ${state.money<normal.total?'disabled':''}>Matin · ${euro(normal.total)}</button><button data-buy="express" data-product="${p.id}" ${state.money<express.total?'disabled':''}>Express · ${euro(express.total)}</button></div></article>`;}).join('');}
function inboundPanel(){const incoming=state.shipments.filter(t=>t.remaining>0||state.workers.some(w=>w.shipment===t.id)),workers=state.workers.filter(w=>w.role==='receiving');return `<div class="stat-grid"><div><span>Articles réceptionnés</span><strong>${state.daily.received}</strong></div><div><span>Réceptionnaires</span><strong>${workers.length}</strong></div></div><button data-switch="stock" class="full">Commander des marchandises</button><h3 class="section-heading">Livraisons fournisseurs</h3>${incoming.map(t=>{const p=state.products.find(p=>p.id===t.productId),cargo=workers.filter(w=>w.shipment===t.id).reduce((n,w)=>n+w.cargo,0),left=t.remaining+cargo,eta=t.eta-warehouseNow(state);return `<article class="card"><div class="card-head"><strong>${p.name}</strong><span class="chip">${t.express?'Camionnette express':'Gros porteur'}</span></div><p>${left} / ${t.quantity} articles restant à ranger</p><div class="progress"><span style="width:${(t.quantity-left)/t.quantity*100}%;background:#8bc6ba"></span></div><span class="muted">${eta>0?'Arrivée '+(eta>720?'demain à '+clock(t.eta):'dans '+eta+' min'):p.onHand>=p.capacity?'En attente · stock plein':'Au quai · déchargement'}</span></article>`;}).join('')||'<p class="list-empty">Aucune livraison attendue.</p>'}<h3 class="section-heading">Équipe au quai</h3>${workers.map(workerCard).join('')||'<p>Affectez un réceptionnaire dans Équipes.</p>'}`;}
function workerCard(w){const o=state.orders.find(o=>o.id===w.job),p=state.products.find(p=>p.id===w.productId);return `<div class="card"><div class="row"><strong>${w.robot?'Robot':'Agent'} ${w.id}</strong><span class="chip ${w.phase==='idle'?'good':''}">${workerPhases[w.phase]}</span></div><p class="muted">${o?o.ref+' · '+orderItems(o):p?p.name:w.robot?'Prélèvement autonome':WAREHOUSE_ROLES[w.role].name}${w.cargo?' · '+w.cargo+' articles transportés':''}${w.retiring?' · départ après la mission':''}</p></div>`;}
function productionPanel(){const workers=state.workers.filter(w=>['picking','packing'].includes(w.role)),stats=warehouseStats(state);return `<div class="stat-grid"><div><span>Au prélèvement</span><strong>${stats.picking}</strong></div><div><span>À emballer / en cours</span><strong>${stats.packing}</strong></div></div><div class="card"><div class="row"><h3>Postes d’emballage</h3><strong>${state.benches} / 3</strong></div><p>${state.workers.filter(w=>w.role==='packing'&&w.phase!=='idle').length} poste(s) occupé(s) · carton : 0,60 € / colis</p><button data-upgrade="bench" ${state.benches>=3||state.money<1800?'disabled':''}>Ajouter un poste · 1 800 €</button></div><button data-switch="team" class="full">Répartir les équipes</button><h3 class="section-heading">Missions en cours</h3>${workers.map(workerCard).join('')}`;}
function dispatchPanel(){const stats=warehouseStats(state);return `<div class="stat-grid"><div><span>Prêts à partir</span><strong>${stats.ready}</strong></div><div><span>En livraison</span><strong>${stats.inTransit}</strong></div></div><button data-dispatch class="primary full" ${stats.ready===0?'disabled':''}>Expédier maintenant · ${stats.ready} colis prêts</button><p>12 colis par camionnette · 22 € de départ + 0,80 € / colis. Encaissement à la livraison.</p><label>Fréquence des départs<select data-policy="dispatchEvery">${[30,60,120].map(n=>`<option value="${n}" ${state.dispatchEvery===n?'selected':''}>Toutes les ${n} minutes</option>`).join('')}</select></label>${state.vans.map((v,i)=>`<article class="card"><div class="card-head"><strong>Camionnette ${i+1}</strong><span class="chip ${v.phase==='idle'?'good':''}">${({idle:'Disponible',loading:'Chargement',outbound:'Livraison',returning:'Retour'})[v.phase]}</span></div><div class="row"><span class="muted">${v.phase==='idle'?'12 places':v.orders.length+' colis · '+Math.ceil(v.remaining)+' min restantes'}</span><span class="muted">${v.phase==='outbound'?DELIVERY_AREAS.find(a=>a.id===v.area)?.name:''}</span></div></article>`).join('')}<button data-upgrade="van" ${state.vans.length>=4||state.money<8000?'disabled':''}>Ajouter une camionnette · 8 000 €</button><h3 class="section-heading">Prêts à charger</h3>${state.orders.filter(o=>o.stage==='ready').slice(0,12).map(orderCard).join('')||'<p>Aucun colis en attente sur le quai.</p>'}`;}
function teamPanel(){return `<p>Les missions en cours se terminent avant le départ d’un agent retiré.</p>${Object.entries(WAREHOUSE_ROLES).map(([role,definition])=>{const actual=state.workers.filter(w=>w.role===role&&!w.robot),active=actual.filter(w=>w.phase!=='idle');return `<article class="card"><div class="row"><h3>${definition.name}</h3><div class="count-control"><button data-staff="${role}" data-count="${state.staff[role]-1}" aria-label="Retirer un agent ${definition.name}" ${state.staff[role]<=0?'disabled':''}>−</button><strong>${state.staff[role]}</strong><button data-staff="${role}" data-count="${state.staff[role]+1}" aria-label="Ajouter un agent ${definition.name}" ${state.staff[role]>=12?'disabled':''}>+</button></div></div><p>${active.length} en mission · ${definition.wage} € / jour / agent${actual.some(w=>w.retiring)?' · départ en fin de mission':''}</p></article>`;}).join('')}<button data-switch="robots" class="full">Ajouter des robots au prélèvement</button><h3 class="section-heading">Charge de travail</h3>${state.workers.filter(w=>!w.robot&&w.phase!=='idle').map(workerCard).join('')||'<p>Les agents attendent leur prochaine mission.</p>'}`;}
function robotPanel(){const robots=state.workers.filter(w=>w.robot);return `<div class="card"><div class="row"><h3>Robots de prélèvement</h3><div class="count-control"><button data-robots="${state.robotTarget-1}" ${state.robotTarget===0?'disabled':''}>−</button><strong>${state.robotTarget}</strong><button data-robots="${state.robotTarget+1}" ${state.robotTarget>=8||state.money<WH_ROBOT.cost?'disabled':''}>+</button></div></div><p>18 000 € à l’achat · 160 € de maintenance et 20 € d’électricité par jour. Autonomes, plus rapides que les préparateurs.</p><div class="row"><span class="muted">${robots.length} en service</span><strong>${euro(robots.length*180)} / jour</strong></div></div>${robots.map(workerCard).join('')||'<p class="list-empty">Aucun robot installé. Vos préparateurs assurent le prélèvement.</p>'}`;}
function financePanel(){const stats=warehouseStats(state),c=warehouseCosts(state),d=state.daily,margin=d.revenue-d.cogs;return `<div class="stat-grid"><div><span>Trésorerie</span><strong>${euro(state.money)}</strong></div><div><span>Valorisation du stock</span><strong>${euro(stats.stockValue)}</strong></div><div><span>Marge sur les ventes</span><strong>${euro(margin)}</strong></div><div><span>Résultat estimé du jour</span><strong>${euro(stats.profit)}</strong></div></div><div class="card"><h3>Aujourd’hui</h3>${[['Encaissements à la livraison',d.revenue],['Coût des marchandises vendues',-d.cogs],['Tournées & frais de réception',-d.transport],['Emballages',-d.packaging],['Primes de contrats',d.bonus],['Charges à la clôture',-c.total]].map(([n,v])=>`<p class="row"><span>${n}</span><strong>${euro(v)}</strong></p>`).join('')}</div><details class="card"><summary>Charges journalières · ${euro(c.total)}</summary>${[['Salaires',c.wages],['Robots',c.robots],['Loyer',c.rent],['Électricité du bâtiment',c.electricity],['Postes et véhicules',c.equipment],['Racks supplémentaires',c.racks]].map(([n,v])=>`<p class="row"><span>${n}</span><strong>${euro(v)}</strong></p>`).join('')}</details><h3 class="section-heading">Suivi des journées</h3>${state.history.length?`<div class="table-wrap"><table><thead><tr><th>Jour</th><th>Livrées</th><th>Dans les délais</th><th>Ventes</th><th>Marge brute</th><th>Après charges</th><th>Trésorerie</th></tr></thead><tbody>${state.history.map(h=>`<tr><td>J${h.day}</td><td>${h.delivered}</td><td>${h.delivered?Math.round(h.onTime/h.delivered*100):100} %</td><td>${euro(h.revenue)}</td><td>${euro(h.revenue-h.cogs)}</td><td>${euro(h.profit)}</td><td>${euro(h.cash)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Le premier bilan sera disponible à 22 h.</p>'}<h3 class="section-heading">Journal des opérations</h3>${state.log.slice(0,15).map(l=>`<div class="log-row"><span class="muted">J${Math.floor(l.at/1440)+1} · ${clock(l.at)}</span><br>${l.text}</div>`).join('')}`;}
function renderPanel(){if(!panel||held||['INPUT','SELECT'].includes(document.activeElement?.tagName)&&$('management-content').contains(document.activeElement))return;const html=({orders:ordersPanel,stock:stockPanel,inbound:inboundPanel,production:productionPanel,dispatch:dispatchPanel,team:teamPanel,robots:robotPanel,finance:financePanel})[panel]();if(lastPanel!==html){const top=$('management-content').scrollTop;$('management-content').innerHTML=html;$('management-content').scrollTop=top;lastPanel=html;}}
function render(){const latest=state.log[0],key=latest?latest.at+latest.text:'';if(key!==lastLogKey){if(lastLogKey&&latest?.tone==='success'&&(/colis livrés|Contrat réussi/.test(latest.text)))notice(latest.text);lastLogKey=key;}const stats=warehouseStats(state);$('day-label').textContent='JOUR '+String(state.day).padStart(2,'0');$('clock').textContent=clock(state.minute);$('shift-label').textContent=state.minute<480?'Préparation du centre':state.minute<1080?'Opérations en cours':'Derniers départs';$('money').textContent=euro(state.money);$('active-count').textContent=stats.active;$('delivered-count').textContent=state.daily.delivered;$('on-time').textContent=stats.onTime+' %';$('profit').textContent=euro(stats.profit);$('profit').classList.toggle('negative',stats.profit<0);$('service-grade').textContent=state.reputation>=95?'A':state.reputation>=85?'B':state.reputation>=70?'C':state.reputation>=50?'D':'E';
 for(const [key,value]of Object.entries({queue:stats.queued,picking:stats.picking,packing:stats.packing,ready:stats.ready,road:stats.inTransit}))$('flow-'+key).textContent=value;
 $('flow-load').textContent=!state.acceptOrders?'Entrées suspendues':stats.late?'Délais à surveiller':stats.active?'Flux actif':'Centre disponible';$('dispatch-count').textContent=stats.ready;$('dispatch-now').disabled=!saveManager?.ready||!stats.ready||!state.vans.some(v=>v.phase==='idle')||!state.workers.some(w=>w.role==='drivers'&&w.phase==='idle'&&!w.retiring);$('intake-toggle').textContent=state.acceptOrders?'Suspendre les commandes':'Reprendre les commandes';
 const alert=stats.blocked?`${stats.blocked} commande(s) attendent du stock.`:stats.late?`${stats.late} commande(s) dépassent leur échéance.`:stats.packing>3?`${stats.packing} commandes à l’emballage : renforcez ce poste.`:'';$('operation-alert').textContent=alert;$('operation-alert').hidden=!alert;
 document.querySelectorAll('[data-speed]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.speed)===state.speed);b.disabled=!saveManager?.ready;});document.querySelectorAll('.world-tools [data-open]').forEach(b=>b.classList.toggle('active',b.dataset.open===panel));
 $('world-status').textContent=state.money<0?'Trésorerie négative · priorisez les livraisons prêtes':`${num(state.products.reduce((n,p)=>n+p.onHand,0))} articles en stock · ${state.workers.filter(w=>!w.robot).length} agents · ${state.workers.filter(w=>w.robot).length} robots`;
 const offered=state.contracts.find(c=>c.status==='offered'&&warehouseNow(state)>=c.opens&&warehouseNow(state)<=c.expires);$('opportunity').hidden=!offered||Boolean(panel)||arranging;if(offered)$('opportunity').innerHTML=`<span class="eyebrow">OPPORTUNITÉ · AVANT ${clock(offered.expires)}</span><h3>${offered.name}</h3><p>${offered.description} · prime ${euro(offered.bonus)}</p><button data-contract="${offered.id}" class="primary">Accepter le contrat</button>`;
 if(performance.now()-lastPanelAt>500){renderPanel();lastPanelAt=performance.now();}}
$('management-content').addEventListener('pointerdown',()=>held=true);window.addEventListener('pointerup',()=>held=false);window.addEventListener('pointercancel',()=>held=false);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.open){openPanel(b.dataset.open);return;}if(b.dataset.switch){openPanel(b.dataset.switch);return;}if(b.dataset.filter){filter=b.dataset.filter;lastPanel='';lastPanelAt=0;render();return;}if(b.dataset.quantity){quantities[b.dataset.product]=Number(b.dataset.quantity);lastPanel='';lastPanelAt=0;render();return;}
 if(b.dataset.buy)act(()=>buyWarehouseSupply(state,b.dataset.product,quantities[b.dataset.product],b.dataset.buy==='express'),'Marchandises commandées.');
 if(b.dataset.staff)act(()=>setWarehouseStaff(state,b.dataset.staff,Number(b.dataset.count)));
 if(b.dataset.robots!==undefined)act(()=>setWarehouseRobots(state,Number(b.dataset.robots)));
 if(b.dataset.upgrade)act(()=>upgradeWarehouse(state,b.dataset.upgrade,b.dataset.product),'Équipement installé.');
 if(b.dataset.contract)act(()=>acceptWarehouseContract(state,Number(b.dataset.contract)),'Contrat accepté.');
 if(b.hasAttribute('data-dispatch'))act(()=>dispatchWarehouse(state),'Tournée lancée.');
 if(b.dataset.intake)act(()=>setWarehousePolicy(state,'acceptOrders',!state.acceptOrders));
 if(b.dataset.speed!==undefined){act(()=>{state.speed=Number(b.dataset.speed);});}
});
$('management-content').addEventListener('change',e=>{if(e.target.dataset.policy)act(()=>setWarehousePolicy(state,e.target.dataset.policy,e.target.value));});
$('panel-close').addEventListener('click',closePanel);$('intake-toggle').addEventListener('click',()=>act(()=>setWarehousePolicy(state,'acceptOrders',!state.acceptOrders)));$('dispatch-now').addEventListener('click',()=>act(()=>dispatchWarehouse(state),'Tournée lancée.'));$('reset-camera').addEventListener('click',()=>scene.resetCamera());
function setArrange(value){if(value&&!saveManager?.ready)return;arranging=value;if(value){state.speed=0;saveManager.changed();closePanel();}$('layout-bar').hidden=!value;$('arrange-toggle').classList.toggle('active',value);scene.setArrange(value);render();}
$('arrange-toggle').addEventListener('click',()=>setArrange(!arranging));$('layout-done').addEventListener('click',()=>setArrange(false));$('layout-rotate').addEventListener('click',()=>{const key=scene.selectedFixture;if(!key){notice('Sélectionnez un rack ou un poste.');return;}const p=warehouseFixture(state,key);act(()=>moveWarehouseFixture(state,key,p.x,p.z,p.rotation===0?Math.PI/2:0),'Équipement tourné.');});
window.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','SELECT','BUTTON','TEXTAREA'].includes(document.activeElement?.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();act(()=>state.speed=state.speed?0:1);}});
function saveStatus(info){saveUi=info;if(!info.ready)state.speed=0;const names={loading:'Chargement…',pending:'À sauvegarder',saving:'Sauvegarde…',saved:'Sauvegardé',error:'Échec de sauvegarde',conflict:'Partie modifiée ailleurs','load-error':'Chargement impossible',offline:'Sauvegardé sur cet appareil'};$('save-status').textContent=info.message||names[info.status];$('save-toggle').title=names[info.status];$('save-toggle').classList.toggle('save-error',['error','conflict','load-error'].includes(info.status));$('save-mode-label').textContent=info.flightMode?'Partie · ✈':'Partie';$('save-flight').textContent=info.flightMode?'Revenir en ligne':'Préparer pour l’avion';$('save-flight').disabled=!info.flightMode&&!info.ready;$('save-local').hidden=info.status!=='conflict';$('save-reload').textContent=info.status==='conflict'?'Reprendre la partie en ligne':'Recharger la sauvegarde';$('save-recovery').hidden=!info.hasRecovery;$('save-previous').disabled=!info.ready||!info.hasPrevious;for(const id of ['save-new','save-now','save-return','save-close','save-export'])$(id).disabled=!info.ready;$('offline-status').textContent=info.ready&&!info.localAvailable?'Sauvegarde locale indisponible sur cet appareil.':offlineMessage;if(['load-error','conflict'].includes(info.status)&&!$('save-dialog').open)$('save-dialog').showModal();}
saveManager=createSaveManager({snapshot:()=>makeSave(state),apply:record=>{let legacyValue=null;if(record.schemaVersion===1){try{legacyValue=stockValuation(structuredClone(record.state)).closingHT;}catch{}}const migrated=migrateWarehouseGame(record,legacyValue);for(const k of Object.keys(state))delete state[k];Object.assign(state,migrated);lastLogKey=state.log[0]?state.log[0].at+state.log[0].text:'';scene.reset();pendingMinutes=0;lastTime=performance.now();lastPanel='';$('migration-info').hidden=!state.transition;if(state.transition)$('migration-info').textContent=`Ancienne partie conservée dans l’export. Capital de reconversion : ${euro(state.initialCash)}${state.transition.support?' dont '+euro(state.transition.support)+' d’apport de lancement':''}.`;render();},notify:saveStatus});
function resume(){if(saveManager.ready){state.speed=1;saveManager.changed();render();$('save-dialog').close();}}
$('save-toggle').addEventListener('click',()=>{state.speed=0;saveManager.changed();saveManager.flush();$('save-dialog').showModal();});for(const id of ['save-close','save-return'])$(id).addEventListener('click',()=>{$('save-dialog').close();$('warehouse-map').focus();});$('save-dialog').addEventListener('cancel',e=>{if(!saveManager.ready)e.preventDefault();});$('save-now').addEventListener('click',()=>saveManager.flush());$('save-reload').addEventListener('click',async()=>{if(await saveManager.load())resume();});$('save-previous').addEventListener('click',()=>saveManager.load(true));$('save-local').addEventListener('click',async()=>{if(await saveManager.keepLocal())resume();});$('save-recovery').addEventListener('click',async()=>{if(await saveManager.recoverLocal())resume();});$('save-new').addEventListener('click',()=>$('save-confirm').hidden=false);$('save-cancel-new').addEventListener('click',()=>$('save-confirm').hidden=true);$('save-confirm-new').addEventListener('click',async()=>{const fresh=createWarehouseGame();if(state.legacyArchive){fresh.legacyArchive=state.legacyArchive;fresh.transition=state.transition;}if(await saveManager.newGame(makeSave(fresh))){$('save-confirm').hidden=true;resume();}});
$('save-export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(makeSave(state),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='flux-centre-logistique.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('save-dialog').showModal();render();
let lastRender=0;function frame(time){const delta=Math.min(.25,(time-lastTime)/1000);lastTime=time;const elapsedMinutes=saveManager.ready&&!arranging&&!document.querySelector('dialog[open]')?delta*state.speed:0;if(elapsedMinutes){pendingMinutes+=elapsedMinutes;if(pendingMinutes>=1){const minutes=Math.floor(pendingMinutes);pendingMinutes-=minutes;advanceWarehouse(state,minutes);saveManager.changed();}}scene.update(delta,{fraction:pendingMinutes,elapsedMinutes});if(time-lastRender>300){render();lastRender=time;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
if(await saveManager.load())resume();
offlineSupport=startOfflineSupport({isFlightMode:()=>saveManager.flightMode,notify:message=>{offlineMessage=message;$('offline-status').textContent=saveUi?.ready&&!saveUi.localAvailable?'Sauvegarde locale indisponible sur cet appareil.':message;},onAuthRequired:()=>saveManager.lockAuth()});
$('save-flight').addEventListener('click',async()=>{$('save-flight').disabled=true;const enabled=!saveManager.flightMode;try{if(enabled){saveManager.changed();await saveManager.flush();if(!saveManager.ready)throw Error('Chargez votre partie avant de préparer le vol.');}await offlineSupport.setFlightMode(enabled);if(!await saveManager.setFlightMode(enabled)){await offlineSupport.setFlightMode(!enabled);return;}if(!enabled){if(saveManager.ready)await saveManager.flush();else if(await saveManager.load())resume();}}catch(error){$('offline-status').textContent=error.message;}finally{$('save-flight').disabled=!saveManager.flightMode&&!saveManager.ready;}});
window.addEventListener('online',()=>saveManager.ready&&saveManager.flush());window.addEventListener('offline',()=>{saveManager.changed();saveManager.flush();});document.addEventListener('visibilitychange',()=>{if(document.hidden){state.speed=0;saveManager.changed();saveManager.flush(true);}lastTime=performance.now();});window.addEventListener('pagehide',()=>{saveManager.changed();saveManager.flush(true);});setInterval(()=>saveManager.flush(),5000);
if(navigator.modelContext?.registerTool){const tools=[{name:'read_fulfillment_status',description:'Lire les stocks, commandes, équipes, tournées et finances du centre logistique.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>structuredClone({...warehouseStats(state),day:state.day,minute:state.minute,products:state.products,orders:state.orders,workers:state.workers,vans:state.vans,contracts:state.contracts})}];for(const tool of tools)try{Promise.resolve(navigator.modelContext.registerTool(tool)).catch(()=>{});}catch{}}
